     "text": "온도가 다른 두 물체가 닿으면 온도가 높은 쪽에서 낮은 쪽으로 열이 이동해요. 이때 높은 쪽의 온도가 내려가고 낮은 쪽이 올라가 두 온도 차이가 줄어드는 모습을 관찰할 수 있어요. 얇은 금속 컵을 사이에 둔 두 물은 섞이지 않아도 열을 주고받을 수 있어요. 처음 값부터 같은 시각에 두 온도를 기록해요. 용기·주위 공기와도 열이 이동할 수 있으며 측정하지 않은 끝 값이나 같아진 시각은 만들어 쓰지 않아요."
