     "text": "단열은 물체 사이 열의 이동을 줄이는 것이에요. 주위가 차가우면 따뜻한 물체에서 밖으로 나가는 열을, 주위가 따뜻하면 차가운 물체에 들어오는 열을 줄이는 데 도움이 돼요. 벽·바닥의 감싸는 재료와 뚜껑 틈, 빛에 의한 전달 등 여러 경로를 생각해요. 재료와 구조·배치에 따라 효과가 달라요. 반사 재료는 특히 사용 배치가 중요하며, 반짝이게 붙였다고 모든 열 이동이 사라지지는 않아요."
