     "text": "온도는 물체가 따뜻하고 차가운 정도예요. 손으로 느끼는 차가움은 손과 물체 사이 열의 이동에도 영향을 받아요. 같은 온도의 재료도 다르게 느껴질 수 있으므로 온도를 비교할 때에는 온도계로 확인해요. 사용 범위와 감지 부분을 확인해요. 물의 온도는 감지 부분을 물속에 두고 벽·바닥과 떨어뜨려 고정해요. 표시가 안정된 뒤 시각·값·℃를 기록해요. 다른 온도계는 제품의 읽는 방법도 확인해요."
